META = dict(
    outline='ಶ್ಲೋಕಗಳು 1–3: ಈ ಯೋಗದ ಪ್ರಾಚೀನ ಪರಂಪರೆ; 4–10: ಭಗವಂತ ಏಕೆ ಮತ್ತು ಯಾವಾಗ ಅವತರಿಸುತ್ತಾನೆ; 11–15: ಜನರು ಅವನನ್ನು ಹೇಗೆ ಸಮೀಪಿಸುತ್ತಾರೋ ಹಾಗೆ ಅವನು ಸ್ಪಂದಿಸುತ್ತಾನೆ, ನಾಲ್ಕು ವರ್ಣಗಳು; 16–24: ಕರ್ಮ, ಅಕರ್ಮ ಮತ್ತು ವಿಕರ್ಮ, ಎಲ್ಲವೂ ಬ್ರಹ್ಮಾರ್ಪಣ; 25–33: ಅನೇಕ ಬಗೆಯ ಯಜ್ಞಗಳು, ಜ್ಞಾನಯಜ್ಞವೇ ಶ್ರೇಷ್ಠ; 34–42: ಗುರುವಿನಿಂದ ಜ್ಞಾನ ಪಡೆ, ಜ್ಞಾನ ಎಲ್ಲ ಕರ್ಮಗಳನ್ನೂ ಸುಟ್ಟುಬಿಡುತ್ತದೆ, ಸಂಶಯ ಕತ್ತರಿಸಿ ಎದ್ದೇಳು.',
)
T = {
1: 'ಶ್ರೀಭಗವಂತ ಹೇಳಿದನು: ಈ ಅವಿನಾಶಿ ಯೋಗವನ್ನು ನಾನು ವಿವಸ್ವಂತನಿಗೆ (ಸೂರ್ಯನಿಗೆ) ಹೇಳಿದೆ; ವಿವಸ್ವಂತ ಮನುವಿಗೆ ಹೇಳಿದನು, ಮನು ಇಕ್ಷ್ವಾಕುವಿಗೆ ಹೇಳಿದನು.',
2: 'ಹೇ ಪರಂತಪ, ಹೀಗೆ ಪರಂಪರೆಯಿಂದ ಬಂದ ಈ ಯೋಗವನ್ನು ರಾಜರ್ಷಿಗಳು ತಿಳಿದಿದ್ದರು. ದೀರ್ಘಕಾಲ ಕಳೆದಂತೆ ಈ ಯೋಗ ಈ ಲೋಕದಲ್ಲಿ ಕಳೆದುಹೋಯಿತು.',
3: 'ಅದೇ ಪುರಾತನ ಯೋಗವನ್ನು ಇಂದು ನಾನು ನಿನಗೆ ಹೇಳಿದ್ದೇನೆ, ಏಕೆಂದರೆ ನೀನು ನನ್ನ ಭಕ್ತ ಮತ್ತು ಸ್ನೇಹಿತ. ಇದು ಉತ್ತಮ ರಹಸ್ಯ.',
4: 'ಅರ್ಜುನ ಹೇಳಿದನು: ನಿಮ್ಮ ಜನ್ಮ ಇತ್ತೀಚಿನದು, ವಿವಸ್ವಂತನ ಜನ್ಮ ಬಹಳ ಹಿಂದಿನದು. ಹಾಗಾದರೆ ಆದಿಯಲ್ಲಿ ನೀವು ಇದನ್ನು ಹೇಳಿದಿರಿ ಎಂದು ನಾನು ಹೇಗೆ ತಿಳಿಯಲಿ?',
5: 'ಶ್ರೀಭಗವಂತ ಹೇಳಿದನು: ಹೇ ಅರ್ಜುನ, ನನಗೂ ನಿನಗೂ ಅನೇಕ ಜನ್ಮಗಳು ಕಳೆದಿವೆ. ಹೇ ಪರಂತಪ, ಅವೆಲ್ಲವನ್ನೂ ನಾನು ತಿಳಿದಿದ್ದೇನೆ, ನೀನು ತಿಳಿಯೆ.',
6: 'ನಾನು ಜನ್ಮರಹಿತನೂ, ಅವಿನಾಶಿ ಸ್ವರೂಪನೂ, ಎಲ್ಲ ಜೀವಿಗಳ ಈಶ್ವರನೂ ಆಗಿದ್ದರೂ, ನನ್ನ ಪ್ರಕೃತಿಯನ್ನು ವಶದಲ್ಲಿಟ್ಟುಕೊಂಡು ನನ್ನ ಯೋಗಮಾಯೆಯಿಂದ ಪ್ರಕಟನಾಗುತ್ತೇನೆ.',
7: 'ಹೇ ಭಾರತ, ಯಾವಾಗ ಯಾವಾಗ ಧರ್ಮಕ್ಕೆ ಹಾನಿಯಾಗಿ ಅಧರ್ಮ ಹೆಚ್ಚುತ್ತದೆಯೋ, ಆಗ ಆಗ ನಾನು ನನ್ನನ್ನು ಸೃಷ್ಟಿಸಿಕೊಳ್ಳುತ್ತೇನೆ (ಪ್ರಕಟನಾಗುತ್ತೇನೆ).',
8: 'ಸಜ್ಜನರನ್ನು ರಕ್ಷಿಸಲು, ದುಷ್ಟರನ್ನು ನಾಶಮಾಡಲು ಮತ್ತು ಧರ್ಮವನ್ನು ಸ್ಥಾಪಿಸಲು ನಾನು ಯುಗಯುಗದಲ್ಲೂ ಪ್ರಕಟನಾಗುತ್ತೇನೆ.',
9: 'ಹೇ ಅರ್ಜುನ, ನನ್ನ ದಿವ್ಯ ಜನ್ಮ ಮತ್ತು ಕರ್ಮವನ್ನು ತತ್ತ್ವವಾಗಿ ತಿಳಿದವನು ದೇಹವನ್ನು ಬಿಟ್ಟ ಮೇಲೆ ಮತ್ತೆ ಹುಟ್ಟುವುದಿಲ್ಲ, ನನ್ನನ್ನೇ ಸೇರುತ್ತಾನೆ.',
10: 'ರಾಗ, ಭಯ ಮತ್ತು ಕ್ರೋಧಗಳಿಂದ ಮುಕ್ತರಾಗಿ, ನನ್ನಲ್ಲಿ ತನ್ಮಯರಾಗಿ, ನನ್ನ ಆಶ್ರಯ ಪಡೆದ ಅನೇಕರು ಜ್ಞಾನದ ತಪಸ್ಸಿನಿಂದ ಶುದ್ಧರಾಗಿ ನನ್ನ ಭಾವವನ್ನು ಪಡೆದಿದ್ದಾರೆ.',
11: 'ಹೇ ಪಾರ್ಥ, ಯಾರು ನನ್ನನ್ನು ಹೇಗೆ ಶರಣು ಬರುತ್ತಾರೋ, ಅವರನ್ನು ನಾನು ಹಾಗೆಯೇ ಭಜಿಸುತ್ತೇನೆ. ಮನುಷ್ಯರು ಎಲ್ಲ ರೀತಿಯಲ್ಲೂ ನನ್ನ ದಾರಿಯನ್ನೇ ಅನುಸರಿಸುತ್ತಾರೆ.',
12: 'ಕರ್ಮಗಳ ಸಿದ್ಧಿಯನ್ನು ಬಯಸುವವರು ಈ ಲೋಕದಲ್ಲಿ ದೇವತೆಗಳನ್ನು ಪೂಜಿಸುತ್ತಾರೆ, ಏಕೆಂದರೆ ಮನುಷ್ಯಲೋಕದಲ್ಲಿ ಕರ್ಮದಿಂದ ಹುಟ್ಟುವ ಸಿದ್ಧಿ ಬೇಗನೆ ಸಿಗುತ್ತದೆ.',
13: 'ಗುಣ ಮತ್ತು ಕರ್ಮಗಳ ವಿಭಾಗದ ಪ್ರಕಾರ ನಾಲ್ಕು ವರ್ಣಗಳನ್ನು ನಾನು ಸೃಷ್ಟಿಸಿದೆ. ಅದರ ಕರ್ತನಾಗಿದ್ದರೂ, ನನ್ನನ್ನು ಅಕರ್ತ ಮತ್ತು ಅವಿನಾಶಿ ಎಂದು ತಿಳಿ.',
14: 'ಕರ್ಮಗಳು ನನಗೆ ಅಂಟುವುದಿಲ್ಲ, ಕರ್ಮಫಲದಲ್ಲಿ ನನಗೆ ಆಸೆಯಿಲ್ಲ. ನನ್ನನ್ನು ಹೀಗೆ ತಿಳಿದವನು ಕರ್ಮಗಳಿಂದ ಬಂಧಿಸಲ್ಪಡುವುದಿಲ್ಲ.',
15: 'ಇದನ್ನು ತಿಳಿದೇ ಹಿಂದಿನ ಮೋಕ್ಷಾರ್ಥಿಗಳೂ ಕರ್ಮ ಮಾಡಿದರು. ಆದ್ದರಿಂದ ಪೂರ್ವಿಕರು ಹಿಂದೆ ಮಾಡಿದಂತೆ ನೀನೂ ಕರ್ಮವನ್ನೇ ಮಾಡು.',
16: 'ಕರ್ಮ ಯಾವುದು, ಅಕರ್ಮ ಯಾವುದು ಎಂಬ ವಿಷಯದಲ್ಲಿ ಜ್ಞಾನಿಗಳೂ ಗೊಂದಲಕ್ಕೊಳಗಾಗಿದ್ದಾರೆ. ಯಾವುದನ್ನು ತಿಳಿದು ನೀನು ಅಶುಭದಿಂದ ಮುಕ್ತನಾಗುತ್ತೀಯೋ ಆ ಕರ್ಮವನ್ನು ನಿನಗೆ ಹೇಳುತ್ತೇನೆ.',
17: 'ಕರ್ಮವನ್ನು ತಿಳಿಯಬೇಕು, ವಿಕರ್ಮವನ್ನು (ನಿಷಿದ್ಧ ಕರ್ಮವನ್ನು) ತಿಳಿಯಬೇಕು, ಅಕರ್ಮವನ್ನೂ ತಿಳಿಯಬೇಕು. ಕರ್ಮದ ಗತಿ ಬಹಳ ಗಹನವಾದುದು.',
18: 'ಕರ್ಮದಲ್ಲಿ ಅಕರ್ಮವನ್ನೂ, ಅಕರ್ಮದಲ್ಲಿ ಕರ್ಮವನ್ನೂ ಕಾಣುವವನು ಮನುಷ್ಯರಲ್ಲಿ ಬುದ್ಧಿವಂತ. ಅವನು ಯೋಗಿ, ಎಲ್ಲ ಕರ್ಮಗಳನ್ನೂ ಮಾಡುವವನು.',
19: 'ಯಾರ ಎಲ್ಲ ಆರಂಭಗಳೂ ಕಾಮನೆ ಮತ್ತು ಸಂಕಲ್ಪಗಳಿಲ್ಲದವೋ, ಯಾರ ಕರ್ಮಗಳು ಜ್ಞಾನಾಗ್ನಿಯಲ್ಲಿ ಸುಟ್ಟುಹೋಗಿವೆಯೋ, ಅವನನ್ನು ಜ್ಞಾನಿಗಳು ಪಂಡಿತ ಎನ್ನುತ್ತಾರೆ.',
20: 'ಕರ್ಮಫಲದ ಆಸಕ್ತಿಯನ್ನು ಬಿಟ್ಟು, ಸದಾ ತೃಪ್ತನಾಗಿ, ಯಾವ ಆಶ್ರಯವನ್ನೂ ಅವಲಂಬಿಸದೆ ಇರುವವನು ಕರ್ಮದಲ್ಲಿ ತೊಡಗಿದ್ದರೂ ಏನನ್ನೂ ಮಾಡುವುದಿಲ್ಲ.',
21: 'ಆಸೆಯಿಲ್ಲದೆ, ಮನಸ್ಸು ಮತ್ತು ದೇಹವನ್ನು ನಿಯಂತ್ರಿಸಿ, ಎಲ್ಲ ಸಂಗ್ರಹವನ್ನೂ ಬಿಟ್ಟು, ಕೇವಲ ದೇಹಕ್ಕಾಗಿ ಕರ್ಮ ಮಾಡುವವನು ಪಾಪವನ್ನು ಪಡೆಯುವುದಿಲ್ಲ.',
22: 'ತಾನಾಗಿ ಸಿಕ್ಕಿದ್ದರಲ್ಲಿ ತೃಪ್ತನಾದ, ದ್ವಂದ್ವಗಳನ್ನು ದಾಟಿದ, ಮತ್ಸರವಿಲ್ಲದ, ಸಿದ್ಧಿ ಮತ್ತು ಅಸಿದ್ಧಿಗಳಲ್ಲಿ ಸಮನಾದವನು ಕರ್ಮ ಮಾಡಿದರೂ ಬಂಧಿಸಲ್ಪಡುವುದಿಲ್ಲ.',
23: 'ಆಸಕ್ತಿ ಹೋದ, ಮುಕ್ತನಾದ, ಜ್ಞಾನದಲ್ಲಿ ಮನಸ್ಸು ನೆಲೆಸಿದ, ಯಜ್ಞಕ್ಕಾಗಿ ಕರ್ಮ ಮಾಡುವವನ ಕರ್ಮವೆಲ್ಲವೂ ಕರಗಿಹೋಗುತ್ತದೆ.',
24: 'ಅರ್ಪಣೆ ಬ್ರಹ್ಮ, ಹವಿಸ್ಸು ಬ್ರಹ್ಮ, ಬ್ರಹ್ಮರೂಪದ ಅಗ್ನಿಯಲ್ಲಿ ಬ್ರಹ್ಮನಿಂದಲೇ ಹೋಮ ಮಾಡಲ್ಪಡುತ್ತದೆ. ಬ್ರಹ್ಮಕರ್ಮದಲ್ಲಿ ತನ್ಮಯನಾದವನು ಬ್ರಹ್ಮವನ್ನೇ ಸೇರುತ್ತಾನೆ.',
25: 'ಕೆಲವು ಯೋಗಿಗಳು ದೇವತೆಗಳಿಗೆ ಯಜ್ಞ ಮಾಡುತ್ತಾರೆ; ಇತರರು ಬ್ರಹ್ಮರೂಪದ ಅಗ್ನಿಯಲ್ಲಿ ಯಜ್ಞದಿಂದಲೇ ಯಜ್ಞವನ್ನು ಅರ್ಪಿಸುತ್ತಾರೆ.',
26: 'ಕೆಲವರು ಶ್ರವಣ ಮುಂತಾದ ಇಂದ್ರಿಯಗಳನ್ನು ಸಂಯಮದ ಅಗ್ನಿಯಲ್ಲಿ ಅರ್ಪಿಸುತ್ತಾರೆ; ಇತರರು ಶಬ್ದ ಮುಂತಾದ ವಿಷಯಗಳನ್ನು ಇಂದ್ರಿಯಗಳ ಅಗ್ನಿಯಲ್ಲಿ ಅರ್ಪಿಸುತ್ತಾರೆ.',
27: 'ಇನ್ನು ಕೆಲವರು ಎಲ್ಲ ಇಂದ್ರಿಯಗಳ ಕರ್ಮಗಳನ್ನೂ ಪ್ರಾಣಗಳ ಕರ್ಮಗಳನ್ನೂ ಜ್ಞಾನದಿಂದ ಬೆಳಗಿದ ಆತ್ಮಸಂಯಮಯೋಗದ ಅಗ್ನಿಯಲ್ಲಿ ಅರ್ಪಿಸುತ್ತಾರೆ.',
28: 'ಕೆಲವರು ದ್ರವ್ಯಯಜ್ಞ, ತಪೋಯಜ್ಞ ಮತ್ತು ಯೋಗಯಜ್ಞ ಮಾಡುತ್ತಾರೆ; ದೃಢವ್ರತದ ಇತರ ಸಾಧಕರು ಸ್ವಾಧ್ಯಾಯ ಮತ್ತು ಜ್ಞಾನಯಜ್ಞ ಮಾಡುತ್ತಾರೆ.',
29: 'ಕೆಲವರು ಪ್ರಾಣವನ್ನು ಅಪಾನದಲ್ಲಿ, ಅಪಾನವನ್ನು ಪ್ರಾಣದಲ್ಲಿ ಅರ್ಪಿಸುತ್ತಾರೆ; ಪ್ರಾಣ ಮತ್ತು ಅಪಾನದ ಗತಿಯನ್ನು ತಡೆದು ಪ್ರಾಣಾಯಾಮದಲ್ಲಿ ನಿರತರಾಗುತ್ತಾರೆ.',
30: 'ಇತರರು ಆಹಾರವನ್ನು ನಿಯಂತ್ರಿಸಿ ಪ್ರಾಣಗಳನ್ನು ಪ್ರಾಣಗಳಲ್ಲಿ ಅರ್ಪಿಸುತ್ತಾರೆ. ಇವರೆಲ್ಲರೂ ಯಜ್ಞವನ್ನು ತಿಳಿದವರು, ಯಜ್ಞದಿಂದ ಪಾಪಗಳು ನಾಶವಾದವರು.',
31: 'ಯಜ್ಞದಲ್ಲಿ ಉಳಿದ ಅಮೃತವನ್ನು ಸೇವಿಸುವವರು ಸನಾತನ ಬ್ರಹ್ಮವನ್ನು ಸೇರುತ್ತಾರೆ. ಹೇ ಕುರುಶ್ರೇಷ್ಠ, ಯಜ್ಞ ಮಾಡದವನಿಗೆ ಈ ಲೋಕವೇ ಇಲ್ಲ, ಪರಲೋಕ ಎಲ್ಲಿಂದ?',
32: 'ಹೀಗೆ ಅನೇಕ ಬಗೆಯ ಯಜ್ಞಗಳು ವೇದದಲ್ಲಿ ವಿಸ್ತಾರವಾಗಿ ಹೇಳಲ್ಪಟ್ಟಿವೆ. ಅವೆಲ್ಲವೂ ಕರ್ಮದಿಂದ ಹುಟ್ಟಿದವು ಎಂದು ತಿಳಿ; ಹೀಗೆ ತಿಳಿದು ನೀನು ಮುಕ್ತನಾಗುತ್ತೀಯ.',
33: 'ಹೇ ಪರಂತಪ, ದ್ರವ್ಯಮಯ ಯಜ್ಞಕ್ಕಿಂತ ಜ್ಞಾನಯಜ್ಞ ಶ್ರೇಷ್ಠ. ಹೇ ಪಾರ್ಥ, ಎಲ್ಲ ಕರ್ಮಗಳೂ ಸಂಪೂರ್ಣವಾಗಿ ಜ್ಞಾನದಲ್ಲಿ ಕೊನೆಗೊಳ್ಳುತ್ತವೆ.',
34: 'ಅದನ್ನು ತತ್ತ್ವದರ್ಶಿ ಜ್ಞಾನಿಗಳಿಂದ ಕಲಿ: ಅವರಿಗೆ ನಮಸ್ಕರಿಸಿ, ಪ್ರಶ್ನಿಸಿ, ಸೇವೆ ಮಾಡಿ. ಅವರು ನಿನಗೆ ಜ್ಞಾನವನ್ನು ಉಪದೇಶಿಸುತ್ತಾರೆ.',
35: 'ಹೇ ಪಾಂಡವ, ಅದನ್ನು ತಿಳಿದ ಮೇಲೆ ನೀನು ಮತ್ತೆ ಹೀಗೆ ಮೋಹಕ್ಕೆ ಒಳಗಾಗುವುದಿಲ್ಲ. ಅದರಿಂದ ಎಲ್ಲ ಜೀವಿಗಳನ್ನೂ ನಿನ್ನಲ್ಲಿ, ನಂತರ ನನ್ನಲ್ಲಿ ಕಾಣುತ್ತೀಯ.',
36: 'ನೀನು ಎಲ್ಲ ಪಾಪಿಗಳಿಗಿಂತ ಹೆಚ್ಚು ಪಾಪಿಯಾಗಿದ್ದರೂ, ಜ್ಞಾನದ ದೋಣಿಯಿಂದ ಎಲ್ಲ ಪಾಪಗಳನ್ನೂ ದಾಟುತ್ತೀಯ.',
37: 'ಹೇ ಅರ್ಜುನ, ಉರಿಯುವ ಬೆಂಕಿ ಕಟ್ಟಿಗೆಗಳನ್ನು ಬೂದಿ ಮಾಡುವಂತೆ, ಜ್ಞಾನಾಗ್ನಿ ಎಲ್ಲ ಕರ್ಮಗಳನ್ನೂ ಬೂದಿ ಮಾಡುತ್ತದೆ.',
39: 'ಶ್ರದ್ಧೆಯುಳ್ಳ, ಅದರಲ್ಲೇ ತೊಡಗಿದ, ಇಂದ್ರಿಯಗಳನ್ನು ಗೆದ್ದವನು ಜ್ಞಾನವನ್ನು ಪಡೆಯುತ್ತಾನೆ. ಜ್ಞಾನವನ್ನು ಪಡೆದ ಮೇಲೆ ಬೇಗನೆ ಪರಮ ಶಾಂತಿಯನ್ನು ಪಡೆಯುತ್ತಾನೆ.',
40: 'ಅಜ್ಞಾನಿ, ಶ್ರದ್ಧೆಯಿಲ್ಲದವನು, ಸಂಶಯಾತ್ಮ ನಾಶವಾಗುತ್ತಾನೆ. ಸಂಶಯಾತ್ಮನಿಗೆ ಈ ಲೋಕವೂ ಇಲ್ಲ, ಪರಲೋಕವೂ ಇಲ್ಲ, ಸುಖವೂ ಇಲ್ಲ.',
41: 'ಹೇ ಧನಂಜಯ, ಯೋಗದಿಂದ ಕರ್ಮಗಳನ್ನು ತ್ಯಜಿಸಿದ, ಜ್ಞಾನದಿಂದ ಸಂಶಯಗಳನ್ನು ಕತ್ತರಿಸಿದ, ಆತ್ಮವಂತನನ್ನು ಕರ್ಮಗಳು ಬಂಧಿಸುವುದಿಲ್ಲ.',
42: 'ಆದ್ದರಿಂದ ಹೇ ಭಾರತ, ಅಜ್ಞಾನದಿಂದ ಹುಟ್ಟಿ ನಿನ್ನ ಹೃದಯದಲ್ಲಿ ನೆಲೆಸಿರುವ ಈ ಸಂಶಯವನ್ನು ಜ್ಞಾನದ ಖಡ್ಗದಿಂದ ಕತ್ತರಿಸಿ, ಯೋಗದಲ್ಲಿ ನೆಲೆಸಿ ಎದ್ದೇಳು.',
}
